\begin{document}
\begin{tikzpicture}[rotate=180]

    \definecolor{deepskyblue}{rgb}{0.173,0.447,0.682}
    \definecolor{orangepeel}{rgb}{0.902, 0.624, 0}
    \definecolor{lightyellow}{rgb}{0.953,0.882,0.388}
    \definecolor{darkgreen}{rgb}{0.271, 0.608, 0.463}
    \definecolor{lightblue}{rgb}{0.484,0.702,0.894}
    \definecolor{rustred}{rgb}{0.784,0.392,0.149}
    \definecolor{fadedpink}{rgb}{0.753,0.494,0.643}



%here we define (without plotting) the points A, B, C, D, O
	\tkzDefPoint(0,0){A}
	\tkzDefPoint(6,0){B}
	\tkzDefPoint(3,0){D}
	\tkzDefPoint(3,-3){C}

% we define the intersection of the two vectors, and we call it O
	\tkzInterLL(A,B)(D,C) \tkzGetPoint{O}

% here we plot the lines through AB, CD
	\tkzMarkSegments[mark=|](A,C C,B)

	\tkzMarkRightAngle[color=lightyellow,fill,size=.4](B,O,C)
	\tkzDrawSegments[very thick](A,C C,B)
	\tkzDrawLines[very thick](C,D)
	\tkzDrawSegments[very thick,color = deepskyblue](A,D D,B)



% here we plot the points
	\tkzDrawPoints[color=black,fill=black,size=2](A,B,C,D)
	%\tkzDrawPoints[color=deepskyblue,fill=deepskyblue,size=9](C,D)
	\tkzLabelPoints[below](A,B)
	\tkzLabelPoints[above right, xshift=-1, yshift=-2](C)
	\tkzLabelPoints[below right](D)
	\tkzLabelSegment[above](D,B){$x+1$} 
	\tkzLabelSegment[above](D,A){$3x-3$}

\end{tikzpicture}


\end{document}

